function_definitions.EditConfig:
func EditConfig(args []string) {
	for len(args) >= 2 {
		field := args[0]
		value := args[1]

		switch field {
		case "extensions", "custom_apps":
			arrayType(featureSection, field, value)
		case "prefs_path", "spotify_path", "current_theme", "color_scheme", "spotify_launch_flags":
			stringType(settingSection, field, value)

		default:
			toggleType(field, value)
		}

		args = args[2:]
	}

	if err := cfg.Write(); err != nil {
		utils.PrintWarning(fmt.Sprintf("Failed to save config: %s", err.Error()))
	}
}

